tput_delete_guard|qual","policies|storage.objects.presentation_output_delete_guard|roles","policies|storage.objects.presentation_output_delete_guard|with_check","policies|storage.objects.presentation_output_insert_guard|cmd","policies|storage.objects.presentation_output_insert_guard|permissive","policies|storage.objects.presentation_output_insert_guard|qual","policies|storage.objects.presentation_output_insert_guard|roles","policies|storage.objects.presentation_output_insert_guard|with_check","policies|storage.objects.presentation_output_read_guard|cmd","policies|storage.objects.presentation_output_read_guard|permissive","policies|storage.objects.presentation_output_read_guard|qual","policies|storage.objects.presentation_output_read_guard|roles","policies|storage.objects.presentation_output_read_guard|with_check","policies|storage.objects.presentation_output_update_guard|cmd","policies|storage.objects.presentation_output_update_guard|permissive","policies|storage.objects.presentation_output_update_guard|qual","policies|storage.objects.presentation_output_update_guard|roles","policies|storage.objects.presentation_output_update_guard|with_check","policies|storage.objects.presentation_service_storage_read|cmd","policies|storage.objects.presentation_service_storage_read|permissive","policies|storage.objects.presentation_service_storage_read|qual","policies|storage.objects.presentation_service_storage_read|roles","policies|storage.objects.presentation_service_storage_read|with_check","policies|storage.objects.presentation_service_storage_write|cmd","policies|storage.objects.presentation_service_storage_write|permissive","policies|storage.objects.presentation_service_storage_write|qual","policies|storage.objects.presentation_service_storage_write|roles","policies|storage.objects.presentation_service_storage_write|with_check","policies|storage.objects.presentation_user_storage_read|cmd","policies|storage.objects.presentation_user_storage_read|permissive","policies|storage.objects.presentation_user_storage_read|qual","policies|storage.objects.presentation_user_storage_read|roles","policies|storage.objects.presentation_user_storage_read|with_check","tables|eps.presentation_asset_grants|acl","tables|eps.presentation_asset_grants|force_rls","tables|eps.presentation_asset_grants|owner","tables|eps.presentation_asset_grants|rls","tables|eps.presentation_processing_config|acl","tables|eps.presentation_processing_config|force_rls","tables|eps.presentation_processing_config|owner","tables|eps.presentation_processing_config|rls","tables|eps.presentation_version_assets|acl","tables|eps.presentation_version_assets|force_rls","tables|eps.presentation_version_assets|owner","tables|eps.presentation_version_assets|rls","tables|eps.presentation_versions|acl","tables|eps.presentation_versions|force_rls","tables|eps.presentation_versions|owner","tables|eps.presentation_versions|rls","tables|eps.review_stage_payloads|acl","tables|eps.version_slides|acl","tables|eps.version_slides|force_rls","tables|eps.version_slides|owner","tables|eps.version_slides|rls","triggers|eps.jobs.presentation_job_lifecycle|definition","triggers|eps.jobs.presentation_job_lifecycle|enabled","triggers|eps.media_assets.presentation_retained_asset|definition","triggers|eps.media_assets.presentation_retained_asset|enabled","triggers|eps.presentation_series.presentation_ready_pointer_guard|definition","triggers|eps.presentation_series.presentation_ready_pointer_guard|enabled","triggers|eps.presentation_version_assets.presentation_pin_immutable|definition","triggers|eps.presentation_version_assets.presentation_pin_immutable|enabled","triggers|eps.presentation_versions.presentation_version_immutable|definition","triggers|eps.presentation_versions.presentation_version_immutable|enabled","triggers|eps.version_slides.presentation_slide_immutable|definition","triggers|eps.version_slides.presentation_slide_immutable|enabled","types|eps.presentation_asset_grants|acl","types|eps.presentation_asset_grants|base","types|eps.presentation_asset_grants|default","types|eps.presentation_asset_grants|enum_labels","types|eps.presentation_asset_grants|kind","types|eps.presentation_asset_grants|not_null","types|eps.presentation_asset_grants|owner","types|eps.presentation_processing_config|acl","types|eps.presentation_processing_config|base","types|eps.presentation_processing_config|default","types|eps.presentation_processing_config|enum_labels","types|eps.presentation_processing_config|kind","types|eps.presentation_processing_config|not_null","types|eps.presentation_processing_config|owner","types|eps.presentation_version_assets|acl","types|eps.presentation_version_assets|base","types|eps.presentation_version_assets|default","types|eps.presentation_version_assets|enum_labels","types|eps.presentation_version_assets|kind","types|eps.presentation_version_assets|not_null","types|eps.presentation_version_assets|owner","types|eps.presentation_versions|acl","types|eps.presentation_versions|base","types|eps.presentation_versions|default","types|eps.presentation_versions|enum_labels","types|eps.presentation_versions|kind","types|eps.presentation_versions|not_null","types|eps.presentation_versions|owner","types|eps.version_slides|acl","types|eps.version_slides|base","types|eps.version_slides|default","types|eps.version_slides|enum_labels","types|eps.version_slides|kind","types|eps.version_slides|not_null","types|eps.version_slides|owner"]'::jsonb;
begin
-- Metadata only. No source bodies, Auth identities, credentials or business rows.
-- Caller fixes search_path and owns the transaction. Object keys exclude OIDs.
with nested as(select jsonb_build_object(
 'functions',(select coalesce(jsonb_object_agg(signature,metadata),'{}')from(
  select p.oid::regprocedure::text signature,jsonb_build_object('owner',p.proowner::regrole::text,'language',(select lanname from pg_language where oid=p.prolang),'returns',pg_get_function_result(p.oid),'identity_arguments',pg_get_function_identity_arguments(p.oid),'argument_defaults',pg_get_expr(p.proargdefaults,0),'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'kind',p.prokind,'support',case when p.prosupport=0 then null else p.prosupport::regproc::text end,'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,'source_sha256',encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex'))metadata
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('eps','public')or n.nspname='storage'and p.proname in('operation','allow_only_operation','allow_any_operation'))s),
 'tables',(select coalesce(jsonb_object_agg(name,metadata),'{}')from(
  select n.nspname||'.'||c.relname name,jsonb_build_object('owner',c.relowner::regrole::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text)metadata
  from pg_class c join pg_namespace n on n.oid=c.relnamespace where(n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets'))and c.relkind='r')s),
 'columns',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'acl',a.attacl::text,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))),'{}')from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where(n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets'))and c.relkind='r'and a.attnum>0 and not a.attisdropped),
 'policies',(select coalesce(jsonb_object_agg(schemaname||'.'||tablename||'.'||policyname,to_jsonb(p)-'schemaname'-'tablename'-'policyname'),'{}')from pg_policies p where schemaname in('eps','public','storage')),
 'constraints',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||k.conname,jsonb_build_object('definition',replace(pg_get_constraintdef(k.oid),E'\r\n',E'\n'))),'{}')from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets')),
 'indexes',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname,jsonb_build_object('definition',replace(pg_get_indexdef(c.oid),E'\r\n',E'\n'),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive)),'{}')from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace join pg_class t on t.oid=i.indrelid where n.nspname in('eps','public')or n.nspname='storage'and t.relname in('objects','buckets')),
 'triggers',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)),'{}')from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where(n.nspname in('eps','public')or n.nspname='storage'and c.relname in('objects','buckets'))and not t.tgisinternal),
 'schemas',(select coalesce(jsonb_object_agg(nspname,jsonb_build_object('owner',nspowner::regrole::text,'acl',nspacl::text)),'{}')from pg_namespace where nspname in('eps','public','storage','auth','extensions')),
 'types',(select coalesce(jsonb_object_agg(n.nspname||'.'||t.typname,jsonb_build_object('owner',t.typowner::regrole::text,'kind',t.typtype,'acl',t.typacl::text,'base',case when t.typbasetype=0 then null else format_type(t.typbasetype,t.typtypmod)end,'not_null',t.typnotnull,'default',t.typdefault,'enum_labels',(select jsonb_agg(enumlabel order by enumsortorder)from pg_enum where enumtypid=t.oid))),'{}')from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in('eps','public')and t.typelem=0),
 'default_acl',(select coalesce(jsonb_object_agg(d.defaclrole::regrole::text||'/'||coalesce(n.nspname,'*')||'/'||d.defaclobjtype::text,jsonb_build_object('acl',d.defaclacl::text)),'{}')from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in('eps','public','storage','auth','extensions')or d.defaclrole::regrole::text like'eps_%'),
 'roles',(select coalesce(jsonb_object_agg(rolname,jsonb_build_object('login',rolcanlogin,'super',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil)),'{}')from pg_roles where rolname like'eps_%'),
 'memberships',(select coalesce(jsonb_object_agg(roleid::regrole::text||'>'||member::regrole::text||'/'||grantor::regrole::text,jsonb_build_object('grantor',grantor::regrole::text,'admin',admin_option,'inherit',inherit_option,'set',set_option)),'{}')from pg_auth_members where roleid::regrole::text like'eps_%'or member::regrole::text like'eps_%')
)payload),flat as(select category.key||'|'||object.key||'|'||field.key key,field.value from nested cross join lateral jsonb_each(payload)category cross join lateral jsonb_each(category.value)object cross join lateral jsonb_each(object.value)field)
select coalesce(jsonb_object_agg(key,value),'{}') into mapped from flat;
 select coalesce(jsonb_object_agg(key,value),'{}') into protected from jsonb_each(mapped) where not (excluded?key);
 select coalesce(jsonb_object_agg(key,value),'{}') into selected from jsonb_each(mapped) where excluded?key;
 if to_regclass('eps.review_processing_config')is not null then
  execute 'select to_jsonb(c)from eps.review_processing_config c where id' into config;
 end if;
 if to_regclass('eps.presentation_templates')is not null then
  execute $template$select to_jsonb(t)from eps.presentation_templates t where key='everyone-casting'and version='1.0.0'$template$ into template;
 end if;
 perform set_config('eps.review_release.compact_catalog',jsonb_build_object(
  'catalog_full_sha256',encode(sha256(convert_to(mapped::text,'UTF8')),'hex'),
  'catalog_protected_sha256',encode(sha256(convert_to(protected::text,'UTF8')),'hex'),
  'catalog_count',(select count(*)from jsonb_each(mapped)),
  'catalog_delta_values',selected,
  'review_state',jsonb_build_object('config',config,'template',template))::text,true);
end $compact_review_catalog$;
-- Fixed initial M05 additions. No payloads, original paths or grant values returned.
-- Created/updated timestamps of the NEW bucket are environmental; all prior
-- buckets are preserved separately as complete row hashes by the readback.
do $m05_new_state$
declare name text;relation_name text;tables jsonb:='{}';amount bigint;checksum text;
 config jsonb;template jsonb;bucket jsonb;
begin
 foreach name in array array['eps.presentation_processing_config','eps.presentation_versions','eps.version_slides','eps.presentation_version_assets','eps.presentation_asset_grants']loop
  if to_regclass(name)is null then tables:=tables||jsonb_build_object(name,null);continue;end if;
  relation_name:=split_part(name,'.',2);
  execute format('select count(*),encode(sha256(convert_to(coalesce(string_agg(to_jsonb(r)::text,E''\n''order by to_jsonb(r)::text),''''),''UTF8'')),''hex'')from eps.%I r',relation_name)into amount,checksum;
  tables:=tables||jsonb_build_object(name,jsonb_build_object('count',amount,'sha256',checksum));
 end loop;
 if to_regclass('eps.presentation_processing_config')is not null then
  execute 'select to_jsonb(c)from eps.presentation_processing_config c where id'into config;
 end if;
 if to_regclass('eps.presentation_templates')is not null then
  select to_jsonb(t)into template from eps.presentation_templates t where key='everyone-casting'and version='1.1.0';
 end if;
 select to_jsonb(b)-array['created_at','updated_at']into bucket from storage.buckets b where id='eps-presentation-outputs';
 perform set_config('eps.presentation_release.new_state',jsonb_build_object('tables',tables,'config',config,'template',template,'bucket',bucket)::text,true);
end $m05_new_state$;
select (current_setting('eps.read_operation_release.snapshot')::jsonb-'catalog')
 ||current_setting('eps.review_release.compact_catalog')::jsonb
 ||jsonb_build_object('m05_state',current_setting('eps.presentation_release.new_state')::jsonb)as m05_presentation_release;
rollback;
